                text: qsTr("Edit")
                color: root.titleColor
                font.pixelSize: 12
                font.weight: Font.Medium
            }
            background: Rectangle {
                radius: height / 2
                color: editButton.pressed ? root.borderColor
                    : (editButton.hovered
                       ? Qt.rgba(root.titleColor.r, root.titleColor.g,
                                 root.titleColor.b, 0.08)
                       : "transparent")
                border.width: 1
                border.color: root.borderColor
            }
            onClicked: {
                root.close()
                root.editRequested()
            }
        }
    }
}

